from typing import List

from taf.selenium.gnb.oam.coam.vdu.interface import vdu

from taf.rfrl.procedures.resources.python.bts.components.rmod.cloud_rmod import CloudRmod
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import pretty_log
from taf.rfrl.procedures.resources.python.bts.webem.webem import Webem


class WebemDu(Webem):
    """ Represents WebEM interface which allows to perform operations on DU using web browser. """

    def __init__(self, sw_stream: str, selenium_alias: str):
        super().__init__(sw_stream, selenium_alias)
        self._selenium = vdu()

    @pretty_log
    def start_antenna_monitoring(self, rmods: List[CloudRmod], timeout: int = 60) -> str:
        """
        Starts the Antenna Line Online Monitoring procedure for antenna lines from RMODs.
        :param rmods: list of RMODs for which antenna lines will be monitored;
        :param timeout: time (in seconds) within the element should be available to be clicked; defaults to 60
        :return: status of starting the Antenna Line Online Monitoring procedure
        """
        rmods = [rmod.name for rmod in rmods]
        return self._selenium.start_antenna_monitoring(antennas=rmods,
                                                       timeout=timeout,
                                                       coam=self._selenium_alias)

    @pretty_log
    def stop_antenna_monitoring(self, timeout: int = 60) -> str:
        """
        Stops the Antenna Line Online Monitoring procedure.
        :param timeout: time (in seconds) within the element should be available to be clicked; defaults to 60
        :return: status of stopping the Antenna Line Online Monitoring procedure
        """
        return self._selenium.stop_antenna_monitoring(timeout=timeout,
                                                      coam=self._selenium_alias)

    @pretty_log
    def get_antenna_monitoring_results(self, timeout: int = 60) -> dict:
        """
        Retrieves the Antenna Line Online Monitoring procedure results from WebEM tables.

        :param timeout: timeout for the element be available to click; defaults to 60
        :return: dictionary with the Antenna Line Online Monitoring procedure results
        """
        return self._selenium.get_antenna_monitoring_results(timeout=timeout,
                                                             coam=self._selenium_alias)

    @pretty_log
    def export_antenna_monitoring_data_to_csv(self, timeout: int = 60) -> str:
        """
        Exports the Antenna Line Online Monitoring procedure results to CSV file

        :param timeout: timeout for the element be available to click; defaults to 60
        :return: path to the downloaded CSV file
        """
        return self._selenium.export_monitoring_data_to_csv(timeout=timeout,
                                                            coam=self._selenium_alias)
